import{_ as i,o as a,c as o,ag as e,j as r}from"./chunks/framework.DoUXNnsN.js";const k=JSON.parse('{"title":"计算机网络","description":"","frontmatter":{"title":"计算机网络","aliases":["计算机网络总览","网络基础","OSI模型","OSI 七层模型","TCP/IP 四层模型","网络分层"],"tags":["计算机基础","计算机网络","总览"],"status":"ai-draft","sources":["https://www.rfc-editor.org/rfc/rfc1122","https://www.rfc-editor.org/rfc/rfc9293","https://www.iana.org/assignments/service-names-port-numbers/service-names-port-numbers.xhtml","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":1},"headers":[],"relativePath":"10-计算机基础/计算机网络/计算机网络.md","filePath":"10-计算机基础/计算机网络/计算机网络.md"}'),s={name:"10-计算机基础/计算机网络/计算机网络.md"},l={style:{"overflow-x":"auto"}},d={viewBox:"0 0 760 330",style:{"min-width":"720px",width:"100%","max-width":"900px"},xmlns:"http://www.w3.org/2000/svg","font-family":"sans-serif","font-size":"14",fill:"currentColor"};function n(h,t,c,p,u,g){return a(),o("div",null,[t[1]||(t[1]=e('<blockquote><p>本篇是&quot;计算机网络&quot;目录的总览页。读完你应该能：说出一次网络访问从应用到网线经过哪几层、每层的&quot;门牌号&quot;是什么；知道后面 7 篇该按什么顺序读；用 <code>ping</code>、<code>tracert</code> 做出第一个网络实验。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>计算机网络就是让两台以上的计算机能互相传数据的一套<strong>约定（协议）<strong>加上</strong>物理线路</strong>。协议负责&quot;怎么说话&quot;，线路负责&quot;话怎么传过去&quot;，而且这些约定是<strong>分层</strong>的：每一层只管自己的事，上层不关心下层怎么实现。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li>会用命令行（Windows 的 PowerShell 或 cmd）敲一条命令并看输出。</li><li>知道&quot;字节&quot;是什么，会看十六进制：<a href="/Encyclopedia/10-计算机基础/数据表示/十六进制">十六进制</a>。</li><li>知道&quot;大端/小端&quot;最好，网络里的多字节数一律用<strong>大端</strong>（高位字节在前）：<a href="/Encyclopedia/10-计算机基础/数据表示/位运算与大小端">位运算与大小端</a>。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>想象你要把一份文件从车间的电脑 A 送到服务器 B。你会立刻遇到一堆问题：</p><ol><li><strong>送给谁？</strong> 要有地址（IP 地址、MAC 地址、域名）。</li><li><strong>走哪条路？</strong> 中间可能隔着十几台设备，要有&quot;选路&quot;的规则（路由）。</li><li><strong>怎么保证不丢不错不乱序？</strong> 线路会出错、会拥堵（TCP 的可靠传输）。</li><li><strong>对方是哪个程序？</strong> 一台电脑上同时有浏览器、数据库、Modbus 软件（端口号）。</li><li><strong>双方怎么理解数据？</strong> 一串字节到底是网页、是温度值还是数据库查询（应用层协议，如 <a href="/Encyclopedia/10-计算机基础/计算机网络/HTTP">HTTP</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a>）。</li></ol><p>如果把所有问题塞进一个巨大的协议，没人写得出来也没法升级。所以人们把问题<strong>分层</strong>解决，就像寄快递：你只管把东西写好地址交给快递员，不用关心他坐飞机还是坐火车。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="协议、报文、封装" tabindex="-1">协议、报文、封装 <a class="header-anchor" href="#协议、报文、封装" aria-label="Permalink to &quot;协议、报文、封装&quot;">​</a></h3><ul><li><strong>协议（protocol）</strong>：通信双方事先约定好的格式和规则。比如&quot;第一个字节表示功能码，后两个字节表示地址&quot;。</li><li><strong>报文/包/帧</strong>：按协议拼出来的一块数据。不同层的叫法不同：应用层叫&quot;报文&quot;，TCP 层叫&quot;段（segment）&quot;，IP 层叫&quot;包（packet）&quot;，以太网层叫&quot;帧（frame）&quot;。</li><li><strong>封装</strong>：数据往下走时，每一层在前面加上自己的&quot;信封&quot;（头部，有时还有尾部）。到了对方那边再一层层拆开。细节见 <a href="/Encyclopedia/10-计算机基础/计算机网络/TCP-IP">TCP-IP</a>。</li></ul><h3 id="两个常见的分层模型" tabindex="-1">两个常见的分层模型 <a class="header-anchor" href="#两个常见的分层模型" aria-label="Permalink to &quot;两个常见的分层模型&quot;">​</a></h3><p><strong>OSI 七层模型</strong>是国际标准化组织定的&quot;理想模型&quot;，适合用来学习和交流（&quot;这是个二层问题&quot;、&quot;七层负载均衡&quot;）。<strong>TCP/IP 模型</strong>是互联网真正用的模型，层数更少。教科书常折中成五层。</p>',14)),r("div",l,[(a(),o("svg",d,[...t[0]||(t[0]=[e('<text x="10" y="22" font-weight="bold">OSI 七层</text><text x="300" y="22" font-weight="bold">TCP/IP（五层教学版）</text><text x="530" y="22" font-weight="bold">例子 / 数据单位 / 门牌号</text><rect x="10" y="32" width="250" height="36" fill="currentColor" fill-opacity="0.08" stroke="currentColor"></rect><text x="20" y="55">7 应用层 Application</text><rect x="10" y="68" width="250" height="36" fill="currentColor" fill-opacity="0.08" stroke="currentColor"></rect><text x="20" y="91">6 表示层 Presentation</text><rect x="10" y="104" width="250" height="36" fill="currentColor" fill-opacity="0.08" stroke="currentColor"></rect><text x="20" y="127">5 会话层 Session</text><rect x="10" y="140" width="250" height="36" fill="currentColor" fill-opacity="0.18" stroke="currentColor"></rect><text x="20" y="163">4 传输层 Transport</text><rect x="10" y="176" width="250" height="36" fill="currentColor" fill-opacity="0.08" stroke="currentColor"></rect><text x="20" y="199">3 网络层 Network</text><rect x="10" y="212" width="250" height="36" fill="currentColor" fill-opacity="0.18" stroke="currentColor"></rect><text x="20" y="235">2 数据链路层 Data Link</text><rect x="10" y="248" width="250" height="36" fill="currentColor" fill-opacity="0.08" stroke="currentColor"></rect><text x="20" y="271">1 物理层 Physical</text><rect x="300" y="32" width="200" height="108" fill="currentColor" fill-opacity="0.12" stroke="currentColor"></rect><text x="310" y="90">应用层（含 5/6/7）</text><rect x="300" y="140" width="200" height="36" fill="currentColor" fill-opacity="0.22" stroke="currentColor"></rect><text x="310" y="163">传输层</text><rect x="300" y="176" width="200" height="36" fill="currentColor" fill-opacity="0.12" stroke="currentColor"></rect><text x="310" y="199">网络层（IP）</text><rect x="300" y="212" width="200" height="72" fill="currentColor" fill-opacity="0.12" stroke="currentColor"></rect><text x="310" y="252">链路层 + 物理层</text><text x="530" y="90">HTTP、DNS、Modbus TCP · 报文</text><text x="530" y="163">TCP / UDP · 段 · 端口号</text><text x="530" y="199">IP · 包 · IP 地址</text><text x="530" y="235">以太网 · 帧 · MAC 地址</text><text x="530" y="271">网线、光纤、Wi-Fi · 比特</text><text x="10" y="315" font-size="12" opacity="0.7">OSI 的 5/6/7 层在实际协议里很难分开，所以 TCP/IP 把它们合成一个&quot;应用层&quot;。</text>',31)])]))]),t[2]||(t[2]=e('<p>记忆方法：从下往上，<strong>物（理）→ 链（路）→ 网（络）→ 传（输）→ 应（用）</strong>。日常说&quot;二层交换机&quot;、&quot;三层交换机&quot;、&quot;四层负载均衡&quot;里的数字，指的就是这里的层号。</p><h3 id="每一层的-门牌号" tabindex="-1">每一层的&quot;门牌号&quot; <a class="header-anchor" href="#每一层的-门牌号" aria-label="Permalink to &quot;每一层的&quot;门牌号&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>用什么标识对方</th><th>例子</th><th>谁来&quot;看&quot;这个地址</th></tr></thead><tbody><tr><td>应用层</td><td>域名/URL</td><td><code>www.example.com</code>、<code>/api/orders</code></td><td>应用程序、<a href="/Encyclopedia/10-计算机基础/计算机网络/DNS">DNS</a></td></tr><tr><td>传输层</td><td>端口号（0~65535）</td><td>80（HTTP）、502（Modbus TCP）</td><td>操作系统，决定交给哪个程序</td></tr><tr><td>网络层</td><td>IP 地址</td><td><code>192.168.1.10</code></td><td>路由器，决定下一跳</td></tr><tr><td>链路层</td><td>MAC 地址</td><td><code>9c-47-82-ce-8c-37</code></td><td>交换机，决定从哪个口出去</td></tr></tbody></table><p>用邮寄来类比：<strong>MAC 地址</strong>像&quot;这栋楼这条走廊上的某个人&quot;，只在局部有效，每过一个路由器就换；<strong>IP 地址</strong>像&quot;省市区街道门牌号&quot;，从头到尾基本不变；<strong>端口号</strong>像&quot;收件人是几楼几号房间里的哪位&quot;。</p><h3 id="常见端口号" tabindex="-1">常见端口号 <a class="header-anchor" href="#常见端口号" aria-label="Permalink to &quot;常见端口号&quot;">​</a></h3><p>下表数据来自 IANA 的端口号登记表（链接见延伸阅读），我逐条查对过：</p><table tabindex="0"><thead><tr><th>端口</th><th>协议</th><th>用途</th></tr></thead><tbody><tr><td>22</td><td>TCP</td><td>SSH 远程登录</td></tr><tr><td>53</td><td>TCP/UDP</td><td><a href="/Encyclopedia/10-计算机基础/计算机网络/DNS">DNS</a> 域名解析</td></tr><tr><td>80</td><td>TCP</td><td><a href="/Encyclopedia/10-计算机基础/计算机网络/HTTP">HTTP</a></td></tr><tr><td>443</td><td>TCP</td><td>HTTPS（HTTP over TLS）</td></tr><tr><td>502</td><td>TCP</td><td>Modbus 应用协议（mbap），见 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a></td></tr><tr><td>1433</td><td>TCP</td><td>Microsoft SQL Server</td></tr><tr><td>1883 / 8883</td><td>TCP</td><td>MQTT / 加密的 MQTT</td></tr><tr><td>3306</td><td>TCP</td><td>MySQL</td></tr><tr><td>4840</td><td>TCP</td><td>OPC UA</td></tr></tbody></table><p>端口号 0~1023 叫&quot;知名端口&quot;，1024~49151 是&quot;注册端口&quot;，49152 以上常被系统用作客户端的<strong>临时端口</strong>（本机用 <code>netsh int ipv4 show dynamicport tcp</code> 查到 Windows 的范围是 49152~65535；Linux 的默认范围不同，用 <code>cat /proc/sys/net/ipv4/ip_local_port_range</code> 查）。这个细节在 <a href="/Encyclopedia/10-计算机基础/计算机网络/TCP与UDP">TCP与UDP</a> 的实验里你会亲眼看到。</p><h3 id="客户端-服务器模式" tabindex="-1">客户端/服务器模式 <a class="header-anchor" href="#客户端-服务器模式" aria-label="Permalink to &quot;客户端/服务器模式&quot;">​</a></h3><p>绝大多数网络程序是&quot;一方等、一方找&quot;：<strong>服务器</strong>先在某个端口上<strong>监听</strong>，<strong>客户端</strong>主动去连。浏览器是客户端，网站是服务器；Modbus 主站是客户端，PLC 是服务器（是的，主站是&quot;客户端&quot;，从站是&quot;服务器&quot;）。注意：客户端的端口号通常是系统随机分配的临时端口，服务器端口是固定的、众所周知的。</p><h2 id="入门路径" tabindex="-1">入门路径 <a class="header-anchor" href="#入门路径" aria-label="Permalink to &quot;入门路径&quot;">​</a></h2><p>下面 7 篇按&quot;从下到上、先概念后动手&quot;的顺序编排，建议依次读，每篇都有可运行的本机实验：</p><ol><li><a href="/Encyclopedia/10-计算机基础/计算机网络/TCP-IP">TCP-IP</a>：先建立全局图：分层、封装、一个数据包的旅程。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/IP地址与子网">IP地址与子网</a>：IP 地址、子网掩码、CIDR、网关。这是排查&quot;为什么 ping 不通&quot;最常用的知识。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/以太网与交换机">以太网与交换机</a>：MAC 地址、ARP、交换机和路由器的区别、VLAN；工厂网络如何分区。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/TCP与UDP">TCP与UDP</a>：传输层：三次握手、可靠性、粘包。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/Socket编程">Socket编程</a>：用 Python 写出真正的 TCP/UDP 客户端和服务器。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/DNS">DNS</a>：域名怎么变成 IP。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/HTTP">HTTP</a>：Web 与各种 API 的基础。</li></ol><p>如果你急着用：做 Modbus TCP/PLC 通信，读 1、2、4、5 就够开工；做 Web/API，读 1、2、4、6、7。读完后可以接着学 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a>、<a href="/Encyclopedia/70-工业通信与自动化/工业以太网">工业以太网</a>、<a href="/Encyclopedia/30-.NET生态/CSharp-TCP通信">CSharp-TCP通信</a>、<a href="/Encyclopedia/30-.NET生态/HttpClient">HttpClient</a>。</p><h2 id="逐步例子-一次-ping-发生了什么" tabindex="-1">逐步例子：一次 ping 发生了什么 <a class="header-anchor" href="#逐步例子-一次-ping-发生了什么" aria-label="Permalink to &quot;逐步例子：一次 ping 发生了什么&quot;">​</a></h2><p>假设你的电脑 IP 是 <code>192.168.62.12</code>，路由器（网关）是 <code>192.168.62.1</code>，你想访问外网的一台服务器。</p><ol><li>你的电脑发现目标 IP <strong>不在</strong>自己所在的网段里（判断方法见 <a href="/Encyclopedia/10-计算机基础/计算机网络/IP地址与子网">IP地址与子网</a>），所以把包交给网关。</li><li>为了把帧发给网关，要先知道网关的 MAC 地址：用 ARP 询问（见 <a href="/Encyclopedia/10-计算机基础/计算机网络/以太网与交换机">以太网与交换机</a>）。</li><li>帧里：目的 MAC = 网关的 MAC，目的 IP = 服务器的 IP。</li><li>路由器收到后拆掉以太网头，看 IP 地址选下一跳，再用新的以太网头封装发出。每过一个路由器，<strong>MAC 变，IP 不变，TTL 减 1</strong>。</li><li>最终到达服务器，一层层拆开，交给对应程序。</li></ol><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>本机实验，不会访问任何外部主机。打开 PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ping </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span></span></code></pre></div><p><code>127.0.0.1</code> 是<strong>回环地址</strong>，数据不出网卡，直接回到自己。我在本机的输出（中文系统）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>来自 127.0.0.1 的回复: 字节=32 时间&lt;1ms TTL=128</span></span></code></pre></div><p><code>TTL=128</code> 是 Windows 默认的初始值（Linux 常见 64）；每经过一个路由器减 1，减到 0 就被丢弃，防止包在网络里无限兜圈。</p><p>再看到本机的&quot;路径&quot;：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tracert </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span></span></code></pre></div><p>输出只有一跳 <code>1 &lt;1 毫秒 &lt;1 毫秒 &lt;1 毫秒 127.0.0.1</code>，因为目标就在本机。</p><p>最后看你的电脑把&quot;所有未知目的地&quot;的包交给谁（默认路由）：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-NetRoute</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AddressFamily IPv4 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DestinationPrefix </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0.0.0.0/0&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Format-Table</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DestinationPrefix</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NextHop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InterfaceAlias</span></span></code></pre></div><p>我的输出里 <code>NextHop</code> 就是路由器地址 <code>192.168.62.1</code>（你的会不同）。<code>0.0.0.0/0</code> 表示&quot;匹配所有地址&quot;。</p><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><p>排查网络问题的黄金法则：<strong>自下而上逐层排查</strong>。</p><table tabindex="0"><thead><tr><th>现象</th><th>先怀疑哪一层</th><th>怎么查</th></tr></thead><tbody><tr><td>网线灯不亮、Wi-Fi 没连上</td><td>物理层</td><td>看指示灯、换线、换口</td></tr><tr><td>能连上但拿不到 IP（<code>169.254.x.x</code>）</td><td>网络层 / DHCP</td><td><code>ipconfig /all</code></td></tr><tr><td>ping 网关不通</td><td>链路层 / IP 配置</td><td>检查子网掩码、网线、VLAN</td></tr><tr><td>ping IP 通，但访问域名失败</td><td>应用层 DNS</td><td><code>nslookup</code>，见 <a href="/Encyclopedia/10-计算机基础/计算机网络/DNS">DNS</a></td></tr><tr><td>ping 通，但程序连不上</td><td>传输层：端口没开、被防火墙挡</td><td><code>Test-NetConnection</code>、<code>netstat</code>，见 <a href="/Encyclopedia/10-计算机基础/计算机网络/TCP与UDP">TCP与UDP</a></td></tr><tr><td>连上了但数据解析错</td><td>应用层协议</td><td>抓包或打印原始字节</td></tr></tbody></table><p>注意：<strong>ping 通只能说明 ICMP 能通</strong>，不代表 TCP 端口能通；有的防火墙会禁止 ping，但业务端口是开的。</p><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>说出下面四个&quot;地址&quot;各属于哪一层：<code>80</code>、<code>192.168.1.10</code>、<code>9c-47-82-ce-8c-37</code>、<code>www.example.com</code>。 <strong>答</strong>：80 是端口（传输层）；192.168.1.10 是 IP（网络层）；9c-47-82-ce-8c-37 是 MAC（链路层）；www.example.com 是域名（应用层）。</li><li>一个包从你的电脑经过 3 个路由器到达服务器，过程中 MAC 地址和 IP 地址分别变了几次？ <strong>答</strong>：IP 源/目的地址基本不变（不考虑 NAT）；MAC 每一跳都重新封装，共 4 段链路，变 3 次（以太网帧在每段链路上的源/目的 MAC 都不同）。</li><li>&quot;二层交换机&quot;和&quot;三层交换机&quot;的区别是什么？ <strong>答</strong>：二层只看 MAC 地址转发；三层还能看 IP 地址做路由。</li><li>为什么 Modbus TCP 主站叫&quot;客户端&quot;？ <strong>答</strong>：网络层面谁主动发起连接谁是客户端。主站主动连 PLC 的 502 端口，所以它是 TCP 客户端，PLC 是 TCP 服务器。</li><li><code>ping</code> 127.0.0.1 成功，能证明网线是好的吗？ <strong>答</strong>：不能。回环地址不经过网卡，只证明本机的 TCP/IP 协议栈工作正常。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>网络靠<strong>分层</strong>和<strong>封装</strong>工作：每层加自己的头，对方一层层拆。</li><li>四种&quot;门牌号&quot;：域名（应用）、端口（传输）、IP（网络）、MAC（链路），各管一段。</li><li>客户端主动找、服务器监听等待；知名端口要记几个：80、443、53、22、502、1433。</li><li>排障自下而上；ping 通不等于业务通。</li><li>学习顺序：<a href="/Encyclopedia/10-计算机基础/计算机网络/TCP-IP">TCP-IP</a> → <a href="/Encyclopedia/10-计算机基础/计算机网络/IP地址与子网">IP地址与子网</a> → <a href="/Encyclopedia/10-计算机基础/计算机网络/以太网与交换机">以太网与交换机</a> → <a href="/Encyclopedia/10-计算机基础/计算机网络/TCP与UDP">TCP与UDP</a> → <a href="/Encyclopedia/10-计算机基础/计算机网络/Socket编程">Socket编程</a> → <a href="/Encyclopedia/10-计算机基础/计算机网络/DNS">DNS</a> → <a href="/Encyclopedia/10-计算机基础/计算机网络/HTTP">HTTP</a>。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/10-计算机基础/计算机网络/TCP-IP">TCP-IP</a>、<a href="/Encyclopedia/10-计算机基础/计算机网络/IP地址与子网">IP地址与子网</a>、<a href="/Encyclopedia/10-计算机基础/计算机网络/以太网与交换机">以太网与交换机</a>、<a href="/Encyclopedia/10-计算机基础/计算机网络/TCP与UDP">TCP与UDP</a>、<a href="/Encyclopedia/10-计算机基础/计算机网络/Socket编程">Socket编程</a>、<a href="/Encyclopedia/10-计算机基础/计算机网络/DNS">DNS</a>、<a href="/Encyclopedia/10-计算机基础/计算机网络/HTTP">HTTP</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a>、<a href="/Encyclopedia/70-工业通信与自动化/工业以太网">工业以太网</a>、<a href="/Encyclopedia/30-.NET生态/CSharp-TCP通信">CSharp-TCP通信</a>、<a href="/Encyclopedia/10-计算机基础/计算机基础">计算机基础</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>RFC 1122，Requirements for Internet Hosts：把互联网主机分成链路、网际、传输、应用四层的经典文档：<a href="https://www.rfc-editor.org/rfc/rfc1122" target="_blank" rel="noreferrer">https://www.rfc-editor.org/rfc/rfc1122</a></li><li>RFC 9293，TCP 的现行规范（2022 年，取代 RFC 793）：<a href="https://www.rfc-editor.org/rfc/rfc9293" target="_blank" rel="noreferrer">https://www.rfc-editor.org/rfc/rfc9293</a></li><li>IANA 端口号登记表：<a href="https://www.iana.org/assignments/service-names-port-numbers/service-names-port-numbers.xhtml" target="_blank" rel="noreferrer">https://www.iana.org/assignments/service-names-port-numbers/service-names-port-numbers.xhtml</a></li></ul>',41))])}const C=i(s,[["render",n]]);export{k as __pageData,C as default};
